  write_json(f'experiments/jobs/{arm}/{b["case_id"]}.json',{'case_id':b['case_id'],'arm':arm,'prompt':prompt,'brief_sha256':digest(Path('experiments/briefs/'+b['case_id']+'.json').read_bytes()),'extra_context_characters':len(extra),'extra_context_utf8_bytes':len(extra.encode()),'model':'unknown','model_selection':'same inherited host model, no override','temperature':'unknown','seed':'unavailable','generation_method':'host_agent_independent_context','max_generation_attempts':1,'expected_output':f'experiments/outputs/{arm}/{b["case_id"]}.md'})
